intentos.respuesta_cruda:
{
  "sql": "SELECT p.product_category_name_english AS categoria, AVG(rv.review_score) AS calificación_promedio, AVG(CASE WHEN e.entrega_con_retraso = 1 THEN 1 ELSE 0 END) AS pct_retrasos, (AVG(CASE WHEN e.entrega_con_retraso = 1 THEN 1 ELSE 0 END) < (SELECT AVG(CASE WHEN e.entrega_con_retraso = 1 THEN 1 ELSE 0 END) FROM vw_entregas_retrasos e)) AS mala_calificación_y_bajo_retraso FROM vw_ventas_pedido v JOIN order_reviews rv ON v.order_id = rv.order_id JOIN products p ON v.product_id = p.product_id LEFT JOIN product_category_translation t ON t.product_category_name = p.product_category_name LEFT JOIN vw_entregas_retrasos e ON v.order_id = e.order_id WHERE p.product_category_name_english IS NOT NULL GROUP BY categoria HAVING COUNT(rv.id) >= 100 AND AVG(rv.review_score) < (SELECT AVG(review_score) FROM order_reviews)"
}
